import { describe, expect, it } from 'vitest';
import { makeInitialForm, productToApiPayload, productToForm } from '@/components/products/product-helpers';
import { buildImportPreview, type RawImportRow } from '@/components/products/import-parser';
import type { ProductRecord } from '@/components/products/types';

/** Product code (SKU), Round B: typed by the user on create / edit (blank = generated by the server); an import row matched by id renames. */
describe('product code (SKU) in the form and the import preview', () => {
  const product = { id: 'p1', name: 'ปูน', sku: '2006893237927', priceLevel1: 150, unit: 'ถุง', barcode: '885123' } as ProductRecord;

  it('a new product form starts blank (blank = the server generates one on save)', () => {
    expect(makeInitialForm().sku).toBe('');
  });

  it('the edit form shows the stored code; the save payload carries the typed code (trimmed, blank = keep / generate)', () => {
    expect(productToForm(product).sku).toBe('2006893237927');
    expect(productToApiPayload(product).sku).toBe('2006893237927');
    expect(productToApiPayload({ ...product, sku: '  MY-CODE ' }).sku).toBe('MY-CODE');
    expect(productToApiPayload({ ...product, sku: '' }).sku).toBe('');
  });

  it('import preview: a row matched by id with another SKU renames it; matched by barcode keeps the code (note only)', () => {
    const row = (r: Partial<RawImportRow>) => ({ 'ชื่อสินค้า': 'ปูน', 'ราคา 1': 150, 'หน่วยนับ': 'ถุง', ...r }) as RawImportRow;
    const [same, renamed, byBarcode] = buildImportPreview([
      row({ 'รหัสสินค้า': '2006893237927' }),
      row({ 'รหัสระบบ (System ID - ห้ามแก้ไข)': 'p1', 'รหัสสินค้า': 'NEW-CODE' }),
      row({ 'รหัสสินค้า': 'OTHER-CODE', 'บาร์โค้ด': '885123', 'ราคา 1': 155 }),
    ], [product]);
    expect(same.changeType).toBe('UNCHANGED');
    expect(renamed).toMatchObject({ changeType: 'CHANGED', id: 'p1', isExisting: true });
    expect(renamed.diffs).toEqual(['รหัสสินค้า: 2006893237927 ➔ NEW-CODE']);
    expect(byBarcode.changeType).toBe('CHANGED');
    expect(byBarcode.diffs).toEqual(['ราคา 1: 150 ➔ 155', 'SKU ในไฟล์ "OTHER-CODE" ไม่ถูกใช้ (คงรหัสเดิม 2006893237927)']);
  });
});
